58	export default async function AdminLayout({ children }: { children: React.ReactNode }) {
59	  // Wrong host (e.g. public nxeon.cloud) → 404, so /admin isn't reachable there.
60	  if (await adminHostBlocked()) notFound();
61	
62	  const user = await realUser();
63	  if (!user) redirect("/login");
64	  if (!isStaff(user.role)) redirect("/dashboard");
65	  const imp = await impersonating();
66	  if (imp) redirect("/dashboard"); // exit impersonation before using admin tools
67	
68	  // IP allow-list: refuse admin access from an IP that isn't explicitly allowed.
69	  if (await adminIpBlocked()) {
70	    return (
71	      <main
72	        style={{
73	          minHeight: "100vh",
74	          display: "flex",
75	          flexDirection: "column",
76	          alignItems: "center",
77	          justifyContent: "center",
78	          gap: "0.75rem",
79	          padding: "2rem",
80	          textAlign: "center",
81	        }}
82	      >
83	        <h1 style={{ fontSize: "1.5rem", fontWeight: 600 }}>Access restricted</h1>
84	        <p style={{ maxWidth: "32rem", opacity: 0.8 }}>
85	          The admin console isn&apos;t available from your current network.
86	        </p>
87	      </main>
88	    );
89	  }
90	
91	  // Staff 2FA enforcement: when enabled, staff without TOTP must set it up before
92	  // using admin tools. Redirect (don't hard-fail) to their security settings so
93	  // they can enroll, then come back.
94	  if ((await getSettingBool("enforce_staff_2fa", false)) && !user.totpEnabled) {
95	    redirect("/dashboard/settings?require2fa=1");
96	  }
97	
98	  // Filter each group's members to what this role can access; drop groups that
99	  // end up empty. The group header will link to its first *accessible* member.
100	  const visibleGroups = ADMIN_GROUPS.map((g) => ({
101	    group: g,
102	    items: g.items.filter((item) => canAccessHref(user.role, item.href)),
103	  })).filter((g) => g.items.length > 0);
104	
105	  const notifications = await db.notification.findMany({
106	    where: { userId: user.id },
107	    orderBy: { createdAt: "desc" },
108	    take: 15,
109	  });
110	
111	  // Attention-count badges for the sidebar. Each count fails soft (→ 0) so a
112	  // missing model/table can never break the admin layout.
113	  const soft = (p: Promise<number>) => p.catch(() => 0);
114	  const [chatUnread, ticketsAwaiting, abuseOpen, feedbackNew, improvementsProposed] = await Promise.all([
115	    // Live chat: conversations flagged unread for agents (same "needs a reply"
116	    // signal the chat inbox sorts/counts by — ChatConversation.unreadForAgent).
117	    soft(db.chatConversation.count({ where: { unreadForAgent: true } })),
118	    // Support desk: tickets awaiting a staff reply (open + customer replies),
119	    // matching the "Awaiting staff" stat on /admin/support.
120	    soft(db.ticket.count({ where: { status: { in: ["OPEN", "CUSTOMER_REPLY"] } } })),
121	    // Abuse queue: alerts still OPEN.
122	    soft(db.abuseAlert.count({ where: { status: "OPEN" } })),
123	    // Feedback: new (untriaged) reports.
124	    soft(db.feedback.count({ where: { status: "NEW" } })),
125	    // Improvements board: proposals awaiting the owner's approve/decline.
126	    soft(db.improvement.count({ where: { status: "PROPOSED" } })),
127	  ]);
128	
129	  // Per-route attention counts, unchanged in meaning from the flat sidebar.
130	  const badges: Record<string, number> = {
131	    "/admin/chat": chatUnread,
132	    "/admin/support": ticketsAwaiting,
133	    "/admin/abuse": abuseOpen,
134	    "/admin/feedback": feedbackNew,
135	    "/admin/improvements": improvementsProposed,
136	  };
137	  // Build the expandable sidebar nav: one entry per visible group, its members
138	  // as children. The header carries the rolled-up group total (shown by the
139	  // Shell only while the group is collapsed); each child carries its own
140	  // per-route count (shown while the group is expanded). The Shell decides which
141	  // group is open from the current path, so the two badge sets never overlap.
142	  const nav: NavSection[] = [
143	    {
144	      items: visibleGroups.map(({ group, items }) => {
145	        const groupTotal = items.reduce((n, item) => n + (badges[item.href] ?? 0), 0);
146	        return {
147	          label: group.label,
148	          href: items[0].href,
149	          icon: group.icon,
150	          badge: groupTotal > 0 ? groupTotal : undefined,
151	          children: items.map((item) => ({
152	            label: item.label,
153	            href: item.href,
154	            badge: badges[item.href] > 0 ? badges[item.href] : undefined,
155	          })),
156	        };
157	      }),
158	    },
159	  ];
160	
161	  return (
162	    <Shell
163	      nav={nav}
164	      tag="ops"
165	      user={{ name: user.name, email: user.email, role: user.role, balanceCents: user.balanceCents }}
166	      notifications={notifications.map((n) => ({
167	        id: n.id,
168	        title: n.title,
169	        body: n.body,
170	        href: n.href,
171	        readAt: n.readAt ? n.readAt.toISOString() : null,
172	        createdAt: n.createdAt.toISOString(),
173	      }))}
174	    >
175	      {children}
176	    </Shell>
177	  );
178	}
